package com.learnagent.analysis;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/analysis")public class AnalysisController{private final AnalysisService service;public AnalysisController(AnalysisService s){service=s;}@GetMapping("/weak-points")public List<AnalysisService.WeakPoint> weak(@RequestParam(required=false)UUID courseId){return service.weakPoints(courseId);}@GetMapping("/statistics")public AnalysisService.Statistics stats(@RequestParam(required=false)UUID courseId){return service.statistics(courseId);}}
